package wgmodern;
import java.util.*;import java.util.concurrent.CompletableFuture;import net.minecraft.data.CachedOutput;import static wgmodern.WGData.*;
public class CompatData {
 public static void add(WGData d,CachedOutput c,List<CompletableFuture<?>> jobs){
  var metals=new ArrayList<>(Metallurgy.METALS);metals.addAll(List.of("iron","gold","copper","tin","silver","lead"));for(String metal:metals){int temp=switch(metal){case "iron","fz_dark_iron","eximite","meutoite"->600;case "gold","tin","lead","nickel"->400;case "copper","aluminum"->350;case "cobalt","ardite"->650;case "manganese"->700;default->550;};jobs.add(d.save(c,"data/witchinggadgets/recipes/compat/melting/"+metal+".json",map("type","witchinggadgets:cluster_melting","conditions",List.of(map("type","forge:mod_loaded","modid","tconstruct"),map("type","witchinggadgets:cluster_melting","metal",metal)),"ingredient",map("tag","forge:clusters/"+metal),"result",map("tag","forge:molten_"+metal,"amount",270),"temperature",temp,"time",Math.max(1,temp/5))));}
  jobs.add(d.save(c,"data/witchinggadgets/recipes/compat/brainjerky.json",map("type","rackitup:drying","conditions",List.of(map("type","forge:mod_loaded","modid","rackitup")),"ingredient",item("thaumcraft:zombie_brain"),"result",item("witchinggadgets:brainjerky"),"time",600)));
  var rows=new ArrayList<Object>();for(String metal:List.of("aluminum","aluminium","aluminum_brass","aluminium_brass","cobalt","ardite","manyullyn","pig_iron")){var extra=new LinkedHashMap<String,Integer>();switch(metal){case "aluminum","aluminium"->extra.put("permutatio",1);case "aluminum_brass","aluminium_brass"->extra.put("permutatio",2);case "cobalt"->{extra.put("ignis",1);extra.put("motus",1);}case "ardite"->{extra.put("ignis",1);extra.put("terra",1);}case "manyullyn"->{extra.put("ignis",2);extra.put("praecantatio",2);}case "pig_iron"->extra.put("corpus",1);}var ingot=new LinkedHashMap<>(extra);ingot.put("metallum",3);row(rows,"forge:ingots/"+metal,ingot);row(rows,"forge:nuggets/"+metal,Map.of("metallum",1));if(metal.equals("pig_iron"))continue;var dust=new LinkedHashMap<>(extra);if(metal.equals("manyullyn")){dust.put("ignis",1);dust.put("praecantatio",1);}dust.put("metallum",2);dust.put("perditio",1);row(rows,"forge:dusts/"+metal,dust);if(metal.equals("manyullyn"))continue;var ore=new LinkedHashMap<>(extra);ore.put("metallum",2);ore.merge("terra",1,Integer::sum);row(rows,"forge:ores/"+metal,ore);}
  row(rows,"forge:bones/wither",Map.of("mortuus",4,"exanimis",2,"fames",2));jobs.add(d.save(c,"data/witchinggadgets/item_aspects/zz_original_compat.json",map("format",1,"entries",List.of(),"witchinggadgets:tag_aspects",rows)));
 }
 private static void row(List<Object> rows,String tag,Map<String,Integer> aspects){rows.add(map("tag",tag,"aspects",aspects.entrySet().stream().map(e->map("aspect",e.getKey(),"amount",e.getValue())).toList()));}
}
